1	/* ===== Đi dạo: nhân vật hiển thị (mình + tối đa 4 người khác) =====
2	   Một InstancedMesh 5 instance (chỉ số = slot đi dạo; đi một mình dùng 0), hình người đi bộ có sẵn (ppBuildGeometry) và vật liệu dùng chung (ppMaterial):
3	   tay chân vung trong shader theo aVar, nên đổi dáng chỉ là ghi 4 số của instance. Lớp 1 (không vào phản chiếu nước), không đổ bóng: thêm đúng 1 lệnh vẽ.
4	   Áo màu multiParams.colors[slot] (như cánh dù), quần một màu tối CONFIG.stroll.pants. Instance trống thu về scale 0; không ai hiện thì mesh.visible = false.
5	   Người khác nội suy bằng ExTrack như remote.ts (trường thứ 6 chở pose, lấy mẫu bậc thang step = true); slot đổi chủ thì xóa mẫu và ẩn tới mẫu đầu.
6	   build() chỉ dựng (lần đầu gọi, không lúc dựng cảnh), bên gọi tự thêm vào scene. Không cấp phát mỗi khung (D-018). */
7	import * as THREE from 'three';
8	import { CONFIG } from '../../config';
9	import { shared } from '../../core/shared';
10	import { ppBuildGeometry } from '../../common/people/shapes';
11	import { ppMaterial } from '../../common/people/material';
12	import { ppAmp, ppCadence, ppStride } from '../../common/people/gait';
13	import { PP_FLAG } from '../../common/people/kinds';
14	import { ExTrack, type ExPose } from '../multi/interp';
15	import type { Flyer } from '../multi/protocol';
16	import { ST_POSE_WALK, ST_POSE_RUN, ST_POSE_PHOTO, type StState } from './motion';
17	
18	const M = CONFIG.explore.multi, C = CONFIG.stroll, N = M.stroll.slots, TAU = Math.PI * 2;
19	
20	/* Thuần: dáng (pose) + tốc độ (m/s) → biên độ hông, nhịp (rad/s của φ), cờ instance (khớp aVar của material.ts).
21	   Nhịp theo tốc độ cho chân trụ không trượt (đi: bước đi; chạy: bước chạy, không chậm hơn nhịp chạy bộ), kẹp ≤ cadenceMax × run.cadence vì 3,5 / 10 m/s nhanh hơn người thật */
22	export function stAvatarVar(pose: number, speed: number, out: { amp: number; cadence: number; flags: number }): void {
23	  const cap = C.cadenceMax * CONFIG.people.run.cadence, v = Math.max(0, speed);
24	  out.amp = 0; out.cadence = 0; out.flags = 0;
25	  if (pose === ST_POSE_WALK) { out.amp = ppAmp('walk'); out.cadence = Math.min(cap, ppCadence('walk', v, 1)); }
26	  else if (pose === ST_POSE_RUN) { out.amp = ppAmp('run'); out.cadence = Math.min(cap, Math.max(ppCadence('run', v, 1), (TAU * v) / ppStride('run', 1))); }
27	  else if (pose === ST_POSE_PHOTO) out.flags = PP_FLAG.photo;
28	}
29	
30	interface StSlot {
31	  who: 0 | 1 | 2;             // 0 trống, 1 mình, 2 người khác
32	  name: string | null;        // tên người khác (từ sync); null = không có
33	  track: ExTrack;
34	  pose: ExPose;               // đệm lấy mẫu (bank chở pose)
35	  st: { x: number; y: number; z: number; yaw: number; pose: number };   // trạng thái trả cho slotState
36	  live: boolean;              // đang hiện
37	  amp: number; cadence: number; flags: number;   // aVar đang ghi (để biết khi nào phải ghi lại)
38	}
39	
40	const slots: StSlot[] = Array.from({ length: N }, () => ({
41	  who: 0 as const, name: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
42	  st: { x: 0, y: 0, z: 0, yaw: 0, pose: 0 }, live: false, amp: -1, cadence: -1, flags: -1
43	}));
44	let mesh: THREE.InstancedMesh | null = null, aVar: THREE.InstancedBufferAttribute | null = null, me = -1;
45	const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _p = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1), _zero = new THREE.Matrix4().makeScale(0, 0, 0), _up = new THREE.Vector3(0, 1, 0);
46	const _var = { amp: 0, cadence: 0, flags: 0 };
47	
48	/* Ghi ma trận và aVar của slot i theo s.st (hoặc thu về scale 0 nếu không hiện); speed cho nhịp bước */
49	function stPlace(i: number, speed: number): void {
50	  const s = slots[i];
51	  if (!mesh || !aVar) return;
52	  if (!s.live) { mesh.setMatrixAt(i, _zero); mesh.instanceMatrix.needsUpdate = true; return; }
53	  const t = s.st;
54	  mesh.setMatrixAt(i, _m.compose(_p.set(t.x, t.y, t.z), _q.setFromAxisAngle(_up, t.yaw), _one));   // hình hướng +X: quay yaw quanh Y ra (cos yaw, 0, −sin yaw)
55	  mesh.instanceMatrix.needsUpdate = true;
56	  stAvatarVar(t.pose, speed, _var);
57	  if (_var.amp === s.amp && _var.cadence === s.cadence && _var.flags === s.flags) return;
58	  const a = aVar.array as Float32Array, o = i * 4, now = shared.uTime.value;
59	  const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
60	  a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
61	  s.amp = _var.amp; s.cadence = _var.cadence; s.flags = _var.flags;
62	  aVar.needsUpdate = true;
63	}
64	
65	function stHide(i: number): void {
66	  const s = slots[i];
67	  s.track.reset(); s.live = false;
68	  stPlace(i, 0);
69	}
70	
71	function stRefreshVisible(): void {
72	  if (!mesh) return;
73	  let any = false;
74	  for (const s of slots) if (s.live) { any = true; break; }
75	  mesh.visible = any;
76	}
77	
78	/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
79	const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);
80	
81	export const stAvatars = {
82	  get mesh(): THREE.InstancedMesh | null { return mesh; },
83	  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)
84	
85	  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại mesh cũ. Bên gọi thêm vào scene */
86	  build(): THREE.InstancedMesh {
87	    if (mesh) return mesh;
88	    const geo = ppBuildGeometry(), col = new THREE.Color();
89	    aVar = new THREE.InstancedBufferAttribute(new Float32Array(N * 4), 4); aVar.setUsage(THREE.DynamicDrawUsage);
90	    const pants = new Float32Array(N * 3);
91	    col.setHex(C.pants);
92	    for (let i = 0; i < N; i++) pants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
93	    geo.setAttribute('aVar', aVar);
94	    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(pants, 3));
95	    mesh = new THREE.InstancedMesh(geo, ppMaterial(), N);
96	    mesh.name = 'stroll-people';
97	    for (let i = 0; i < N; i++) { mesh.setColorAt(i, col.set(M.colors[i % M.colors.length])); mesh.setMatrixAt(i, _zero); }   // setColorAt bắt buộc (USE_INSTANCING_COLOR)
98	    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
99	    mesh.layers.set(1); mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
100	    for (const s of slots) s.amp = s.cadence = s.flags = -1;
101	    for (let i = 0; i < N; i++) stPlace(i, 0);
102	    stRefreshVisible();
103	    return mesh;
104	  },
105	
106	  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó */
107	  setSelf(slot: number, s: StState | null): void {
108	    if (s === null) {
109	      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
110	      me = -1; stRefreshVisible(); return;
111	    }
112	    const x = slots[slot];
113	    if (!x) return;
114	    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
115	    me = slot; x.who = 1; x.track.reset();
116	    const t = x.st;
117	    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
118	    x.live = true;
119	    stPlace(slot, s.speed);
120	    stRefreshVisible();
121	  },
122	
123	  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
124	  sync(walkers: Flyer[], mySlot: number): void {
125	    if (mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }   // đổi slot của mình: setSelf sẽ đặt lại
126	    for (let i = 0; i < N; i++) {
127	      const s = slots[i];
128	      let name: string | null = null;
129	      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
130	      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
131	      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
132	      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
133	    }
134	    stRefreshVisible();
135	  },
136	
137	  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
138	  onPos(w: number[][], nowMs: number): void {
139	    for (const e of w) {
140	      const i = e[0], s = slots[i];
141	      if (!s || i === me || s.who !== 2) continue;
142	      s.track.feed(e, nowMs, M);
143	    }
144	  },
145	
146	  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang) */
147	  update(nowMs: number): void {
148	    const t = nowMs - M.interpSends * 1000 / M.sendHz;
149	    for (let i = 0; i < N; i++) {
150	      const s = slots[i];
151	      if (s.who !== 2) continue;
152	      if (!s.track.sample(t, s.pose, true)) { if (s.live) { s.live = false; stPlace(i, 0); } continue; }
153	      const p = s.pose, st = s.st;
154	      st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.pose = Math.round(p.bank);
155	      s.live = true;
156	      stPlace(i, stPoseSpeed(st.pose));
157	    }
158	    stRefreshVisible();
159	  },
160	
161	  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
162	  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
163	    const s = slots[slot];
164	    return s && s.live ? s.st : null;
165	  },
166	
167	  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
168	  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },
169	
170	  /* Rời chế độ / rời phòng: ẩn hết, quên tên (mesh giữ lại để tái dùng) */
171	  clear(): void {
172	    me = -1;
173	    for (let i = 0; i < N; i++) { const s = slots[i]; s.who = 0; s.name = null; stHide(i); }
174	    stRefreshVisible();
175	  }
176	};
