1	/* ============================ Đi dạo: điều phối chế độ (một mình hoặc nhiều người, máy tính) ============================
2	   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
3	   `?explore=stroll` vào thẳng, đi một mình (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
4	   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
5	   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
6	   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
7	   - Không có nhảy (D-030): Space chỉ bị chặn hành vi mặc định (không cuộn trang, không bấm nút đang focus), không vào keys.
8	   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
9	   - Nhiều người (exMulti, phiên kind 'walk'): xuất phát theo slot đi dạo, gửi vị trí + dáng; hết chỗ thì chế độ xem (startWatching) đặt camera sau lưng người được xem.
10	     Đổi phiên như dù lượn: bị thu chỗ → xem; mất kết nối khi đang đi → đi tiếp một mình + thông báo; mất kết nối khi xem → thoát, màn chọn báo mất kết nối.
11	   - Rời máy: phím điều khiển, kéo chuột và chạm cảm ứng gọi exMulti.activity().
12	   - Cảm ứng (touch.ts, #stHud): cần gạt ghi đè phím khi đang được giữ; vuốt nửa phải xoay camera; 📷 và phím P gọi stPhoto (photo.ts: chụp canvas sau lệnh vẽ chính).
13	   Mỗi khung không cấp phát (D-018). */
14	import { scene, camera, controls, canvas } from '../../core/renderer';
15	import { cam, keys } from '../../views/state';
16	import { CONFIG } from '../../config';
17	import { stSetGate, type StMap } from './map';
18	import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
19	import { stCreate, stStep, stPhotoPose, type StState, type StInput } from './motion';
20	import { stPhotoRequest, stPhotoAfterRender, stPhotoLast } from './photo';
21	import { stAvatars } from './avatars';
22	import { stCollectRuntime } from './sceneData';
23	import { stCamPlace, stCamDrag, type StCam } from './camera';
24	import { stInputFromKeys, stKeyName } from './keys';
25	import { stTouchBind } from './touch';
26	import { exNightStep } from '../nightShows';
27	import { exMulti } from '../multi';
28	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
29	import type { SwingController } from '../../bridges/song-han/SwingController';
30	
31	const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
32	const ST_SOLO_AVATAR = 0;    // instance nhân vật khi đi một mình (avatars.ts)
33	
34	let map: StMap | null = null;
35	let state: StState | null = null;
36	let ctrl: SwingController | null = null;
37	let exit: () => void = () => {};   // thoát chung (explore.exit), do setupStroll nhận
38	let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
39	let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
40	let touch: ReturnType<typeof stTouchBind> | null = null;   // điều khiển cảm ứng (setupStroll dựng)
41	let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
42	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
43	const _inp: StInput = { mx: 0, mz: 0, run: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
44	
45	const active = () => cam.mode === 'stroll' && state !== null;
46	const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
47	/* Chụp ảnh (nút 📷, phím P): giơ tay (dáng 4, tới người khác qua gói vị trí kế tiếp), chớp màn hình, xếp yêu cầu chụp cho sau lệnh vẽ */
48	let flashTimer = 0;
49	function stPhoto(): void {
50	  if (!active()) return;
51	  stPhotoPose(state!);
52	  const f = document.getElementById('stFlash');
53	  if (f) { f.classList.add('on'); clearTimeout(flashTimer); flashTimer = window.setTimeout(() => f.classList.remove('on'), CONFIG.stroll.flashMs); }
54	  stPhotoRequest();
55	}
56	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
57	
58	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
59	function advance(dt: number, inp: StInput): void {
60	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
61	  stStep(state!, inp, map!, dt);
62	  stAvatars.setSelf(selfSlot, state);
63	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
64	  exNightStep(dt, false);
65	  const now = performance.now();
66	  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
67	  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
68	}
69	
70	/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
71	function watchStep(dt: number): void {
72	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
73	  exMulti.update(dt, performance.now(), null);
74	  const w = exMulti.watchWalker();
75	  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
76	  exNightStep(dt, false);
77	}
78	
79	/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
80	function stOnMultiChange(): void {
81	  const s = exMulti.session; if (!s) return;
82	  if (watching) {
83	    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
84	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lostWalk'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện stLostChooser (nhắc Đi dạo, không phải Dù lượn)
85	    exWatchRender();
86	  } else if (active()) {
87	    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
88	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
89	  }
90	}
91	
92	/* Bản đồ dựng lần đầu vào chế độ (đi hoặc xem); cổng nhịp quay theo cầu hiện tại */
93	function stEnsureMap(): StMap {
94	  if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
95	  if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
96	  return map;
97	}
98	
99	export const stroll = {
100	  active,
101	  inMode,
102	  get watching(): boolean { return watching; },
103	  get state(): StState | null { return state; },
104	  get map(): StMap | null { return map; },
105	  get cam(): StCam { return camS; },
106	  /* Vào đi: một mình (không phiên / ngoại tuyến) hoặc với slot đi dạo vừa được cấp (xuất phát lệch theo slot) */
107	  start(): void {
108	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
109	    const m = stEnsureMap(), s = exMulti.session;
110	    const slot = s && s.kind === 'walk' && s.mySlot >= 0 ? s.mySlot : ST_SOLO_SLOT;
111	    if (s) exMulti.onChange = stOnMultiChange;
112	    selfSlot = slot >= 0 ? slot : ST_SOLO_AVATAR;
113	    state = stCreate(m, slot);
114	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
115	    const mesh = stAvatars.build();
116	    if (!mesh.parent) scene.add(mesh);
117	    stAvatars.setSelf(selfSlot, state);
118	    keys.clear(); if (touch) touch.reset();
119	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
120	    stCamPlace(camera, controls.target, state, camS, m, 0, true);
121	    document.body.classList.add('explore', 'stroll');
122	  },
123	  /* Chế độ xem: cam.mode = 'stroll' nhưng không có nhân vật của mình; carry = true khi vừa nhường chỗ (camera đang ở sau lưng mình, trượt dần sang người được xem) */
124	  startWatching(carry = false): void {
125	    const s = exMulti.session; if (!s) return;
126	    stEnsureMap();
127	    const mesh = stAvatars.build();
