100	export const exMulti = {
101	  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
102	  url(): string {
103	    const q = new URLSearchParams(location.search);
104	    if (!q.has('test')) return M.url;
105	    return q.get('multi') ?? '';
106	  },
107	  get session(): MultiSession | null { return session; },
108	  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test
109	
110	  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo); onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
111	  begin(onReady: () => void, kind: Kind = 'fly'): boolean {
112	    const url = exMulti.url();
113	    if (!url || session) return false;
114	    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
115	    let ready = false;
116	    s.onPos = f => exRemotes.onPos(f, performance.now());
117	    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
118	    s.onChange = () => {
119	      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
120	      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
121	      if (s.phase === 'solo') exLabelsClear();
122	      renderRoster();
123	      if (s.phase === 'flying') idleStart(); else idleStop();
124	      exMulti.onChange();
125	      if (!ready) { ready = true; onReady(); }
126	    };
127	    s.open();
128	    return true;
129	  },
130	
131	  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
132	  end(): void {
133	    if (!session) return;
134	    session.dispose(); session = null;
135	    exMulti.onChange = () => {};
136	    idleStop(); exRemotes.clear(); stAvatars.clear(); exLabelsClear();
137	    rosterKey = ''; renderRoster();
138	  },
139	
140	  /* Mỗi khung (bay, đi dạo hoặc xem): dù người khác, người đi dạo khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
141	  update(_dt: number, nowMs: number, state: GliderState | null): void {
