1	/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
2	   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
3	   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
4	import * as THREE from 'three';
5	import { scene, camera, controls } from '../core/renderer';
6	import { cam, keys } from '../views/state';
7	import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
8	import { exBuildGlider, exPlaceGlider } from './glider';
9	import { exChase } from './chase';
10	import { exShowChooser } from './chooser';
11	import { exNight, exNightBind, exNightStep } from './nightShows';
12	import { exMulti } from './multi';
13	import { stroll, setupStroll } from './stroll';
14	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
15	import { CONFIG } from '../config';
16	import type { SwingController } from '../bridges/song-han/SwingController';
17	
18	const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung
19	
20	let glider: THREE.Group | null = null;
21	let state: GliderState | null = null;
22	let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
23	let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
24	let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi
25	
26	const active = () => cam.mode === 'glider' && state !== null;
27	const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem
28	
29	/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
30	function watchStep(dt: number): void {
31	  exMulti.update(dt, performance.now(), null);
32	  const st = exMulti.watchState();
33	  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
34	  exNightStep(dt);
35	}
36	
37	/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
38	function onMultiChange(): void {
39	  const s = exMulti.session; if (!s) return;
40	  if (watching) {
41	    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
42	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
43	    exWatchRender();
44	  } else if (active()) {
45	    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
46	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
47	  }
48	}
49	
50	/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
51	function exShowSpeed(): void {
52	  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
53	  if (t === readout) return;
54	  readout = t;
55	  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
56	}
57	
58	/* Một bước: mô phỏng, đặt dù, đặt camera bám */
59	function advance(dt: number, inp: GliderInput): void {
60	  exStep(state!, inp, dt);
61	  exPlaceGlider(glider!, state!);
62	  exChase(camera, controls.target, state!, dt);
63	  exShowSpeed();
64	  exNightStep(dt);
65	  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
66	}
67	
68	export const explore = {
69	  active,
70	  nightShows: exNight,
71	  get state() { return state; },
72	  get glider() { return glider; },
73	  get watching() { return watching; },
74	  start(): void {
75	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
76	    exMulti.onChange = onMultiChange;
77	    state = exCreate();
78	    const slot = exMulti.session ? exMulti.session.mySlot : -1;
79	    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
80	    if (!glider) glider = exBuildGlider();
81	    if (!glider.parent) scene.add(glider);
82	    glider.visible = true;
83	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
84	    exPlaceGlider(glider, state);
85	    exChase(camera, controls.target, state, 0, true);
86	    exShowSpeed();
87	    document.body.classList.add('explore');
88	  },
89	  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
90	  startWatching(carry = false): void {
91	    const s = exMulti.session; if (!s) return;
92	    watching = true; chased = carry;
93	    keys.clear();
94	    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
95	    document.body.classList.add('explore', 'ex-watching');
96	    exMulti.onChange = onMultiChange;
97	    exWatchShow(s);
98	  },
99	  update(dt: number): void {
100	    if (watching) { watchStep(dt); return; }
101	    if (!active()) return;
102	    advance(dt, exInputFromKeys(keys, _inp));
103	  },
104	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
105	  step(dt: number, inp: GliderInput): void {
106	    if (active()) advance(dt, inp);
107	  },
108	  exit(): void {
109	    const u = new URL(location.href);
110	    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
111	    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
112	    else location.replace(u.toString());
113	  },
114	};
115	
116	export function setupExplore(ctrl: SwingController): void {
117	  exNightBind(ctrl);
118	  setupStroll(ctrl, () => explore.exit());
119	  window.addEventListener('keydown', (e) => {
120	    if (!inGlider() && !stroll.inMode()) return;
121	    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo và hai chế độ xem)
122	    if (watching || stroll.inMode()) return;   // xem: không lái; đi dạo: phím do stroll/index.ts ghi
123	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
124	    const t = e.target as HTMLElement | null;
125	    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
126	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
127	    const k = e.key.toLowerCase(); keys.add(k);
128	    if (k.startsWith('arrow')) e.preventDefault();
129	  });
130	  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
131	  for (const id of ['langSelect', 'qualitySel']) {
132	    const sel = document.getElementById(id); if (!sel) continue;
133	    let byMouse = false;
134	    sel.addEventListener('pointerdown', () => { byMouse = true; });
135	    sel.addEventListener('keydown', () => { byMouse = false; });
136	    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active())) sel.blur(); byMouse = false; });
137	  }
138	  const q = new URLSearchParams(location.search);
139	  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
140	  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
141	  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
142	  if (q.get('explore') === 'glider') { explore.start(); return; }
143	  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
144	  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); },
145	    (choice) => { if (choice === 'walk') stroll.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
146	}
